Aqui está uma implementação eficiente com complexidade O(n) de tempo e O(1) de espaço:

def fibonacci(n: int) -> int:
    if n < 0:
        raise ValueError('O valor de n deve ser não-negativo.')
    if n in (0, 1):
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b
